 try{csrf();if(!$traveler)throw new RuntimeException('Selecciona un tipo de cuenta.');$id=$service->registerTraveler((string)($_POST['display_name']??''),(string)($_POST['email']??''),(string)($_POST['password']??''),(string)($_POST['password_confirm']??''),($_POST['consent']??'')==='1');session_regenerate_id(true);$_SESSION['business_account_id']=$id;$_SESSION['business_last_seen']=time();unset($_SESSION['admin'],$_SESSION['admin_account_id']);$_SESSION['csrf']=bin2hex(random_bytes(32));header('Location: /negocios/portal/',true,303);exit;}
 catch(Throwable $e){$error=$e instanceof PDOException?'No se pudo crear la cuenta. Si ya tienes una con este correo, inicia sesión.':$e->getMessage();http_response_code(400);}
