?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Crear cuenta | Explorando Lugares</title><link rel="stylesheet" href="/assets/style.css"><link rel="stylesheet" href="/assets/account-registration.css?v=1"></head><body><?php require __DIR__.'/../_account-header.php'; ?><main class="wrap account-portal"><section class="account-portal-card"><p class="eyebrow">Explorando Lugares</p><h1><?= $traveler?'Crea tu cuenta de viajero':'¿Cómo quieres participar?' ?></h1><?php if(!$traveler):?><div class="registration-type-grid"><a href="/negocios/registro/?tipo=traveler"><strong>Viajero o turista</strong><span>Explora lugares y accede con tu cuenta personal.</span></a><a href="/negocios/registro/?tipo=business"><strong>Negocio</strong><span>Reclama un negocio existente o registra uno nuevo.</span></a></div><?php else:?><p><a href="/negocios/registro/">Cambiar tipo de cuenta</a></p><?php if($error):?><p role="alert" class="notice"><?=esc($error)?></p><?php endif ?><form method="post" class="registration-form"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="account_type" value="traveler"><label>Tu nombre<input name="display_name" maxlength="180" required autocomplete="name" value="<?=esc($_POST['display_name']??'')?>"></label><label>Correo electrónico<input name="email" type="email" maxlength="254" required autocomplete="email" value="<?=esc($_POST['email']??'')?>"></label><label>Contraseña<input name="password" type="password" minlength="12" maxlength="200" required autocomplete="new-password"><small>Al menos 12 caracteres, con letras y números.</small></label><label>Confirma la contraseña<input name="password_confirm" type="password" minlength="12" maxlength="200" required autocomplete="new-password"></label><label class="registration-consent"><input type="checkbox" name="consent" value="1" required><span>Acepto el tratamiento de mis datos para crear y gestionar mi cuenta según la <a href="/privacidad/">política de privacidad</a>.</span></label><button class="pill" type="submit">Crear cuenta</button></form><?php endif ?><p>¿Ya tienes cuenta? <a href="/negocios/acceso/">Iniciar sesión</a></p></section></main></body></html>
